function generateFen(board, turn) {
  let fen = '';
  for (let r = 0; r < 8; r++) {
    let empty = 0;
    for (let c = 0; c < 8; c++) {
      const p = board[r][c];
      if (!p) { empty++; }
      else {
        if (empty > 0) { fen += empty; empty = 0; }
        const ch = p.type === 'n' ? 'n' : p.type;
        fen += p.color === 'w' ? ch.toUpperCase() : ch.toLowerCase();
      }
    }
    if (empty > 0) fen += empty;
    if (r < 7) fen += '/';
  }
  fen += ' ' + turn + ' KQkq - 0 1';
  return fen;
}

function generatePgn(moves, whiteName, blackName, result) {
  let dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, '.');
  let pgn = '[Event "BSMS Chess Arena"]\n';
  pgn += '[Site "BSMS Web - https://bsms-web.com/chess"]\n';
  pgn += '[Date "' + dateStr + '"]\n';
  pgn += '[White "' + (whiteName || 'Player') + '"]\n';
  pgn += '[Black "' + (blackName || 'Opponent') + '"]\n';
  pgn += '[Result "' + (result || '*') + '"]\n\n';
  for (let i = 0; i < moves.length; i += 2) {
    const moveNum = Math.floor(i / 2) + 1;
    pgn += moveNum + '. ' + (moves[i]?.san || '') + ' ';
    if (moves[i + 1]) pgn += (moves[i + 1]?.san || '') + ' ';
  }
  return pgn.trim();
}
